package cn.zhuatech.traceability.deep;import cn.zhuatech.traceability.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/trace-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/batches")ApiResponse<?> batch(@Valid @RequestBody DeepDomainService.BatchRequest r){return ApiResponse.ok(s.batch(r));}@PostMapping("/batches/{id}/inspections")ApiResponse<?> inspect(@PathVariable Long id,@Valid @RequestBody DeepDomainService.InspectionRequest r){return ApiResponse.ok(s.inspect(id,r));}@PostMapping("/genealogy")ApiResponse<?> consume(@Valid @RequestBody DeepDomainService.GenealogyRequest r){return ApiResponse.ok(s.consume(r));}@PostMapping("/batches/{id}/events")ApiResponse<?> event(@PathVariable Long id,@Valid @RequestBody DeepDomainService.EventRequest r){return ApiResponse.ok(s.event(id,r));}@PostMapping("/recalls")ApiResponse<?> recall(@Valid @RequestBody DeepDomainService.RecallRequest r){return ApiResponse.ok(s.recall(r));}@PostMapping("/recalls/{id}/notify")ApiResponse<?> notify(@PathVariable Long id){return ApiResponse.ok(s.notifyRecall(id));}}
